import{_ as t,a0 as l,w as o,s as d,I as a,x as n,a1 as i,A as p,ao as r}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const x=JSON.parse('{"title":"用 AWK 喝咖啡 | LCTT x X-CMD","titleTemplate":false,"description":"用 AWK 喝咖啡 | LCTT (201902) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"用 AWK 喝咖啡 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"用 AWK 喝咖啡 | LCTT (201902) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201902/20190214 Drinking coffee with AWK","title":"用 AWK 喝咖啡","tag":"201902","desc":""},"relativePath":"201902/20190214 Drinking coffee with AWK.md","filePath":"[post].md"}'),g={name:"201902/20190214 Drinking coffee with AWK.md"};function u(h,s,k,b,m,c){const e=l("Link");return o(),d("div",null,[s[18]||(s[18]=a("h1",{id:"用-awk-喝咖啡",tabindex:"-1"},[n("用 AWK 喝咖啡 "),a("a",{class:"header-anchor",href:"#用-awk-喝咖啡","aria-label":"Permalink to “用 AWK 喝咖啡”"},"​")],-1)),s[19]||(s[19]=a("blockquote",null,[a("p",null,"用一個簡單的 AWK 程序跟蹤你的同事喝咖啡的欠款。")],-1)),s[20]||(s[20]=a("p",null,[a("img",{src:"https://opensource.com/sites/default/files/styles/image-full-size/public/lead-images/coffee_cafe_brew_laptop_desktop.jpg?itok=G-n1o1-o",alt:""})],-1)),s[21]||(s[21]=a("p",null,"以下基於一個真實的故事，雖然一些名字和細節有所改變。",-1)),s[22]||(s[22]=a("blockquote",null,[a("p",null,[n("很久以前，在一個遙遠的地方，有一間"),a("s",null,"廟"),n("（劃掉）辦公室。由於各種原因，這個辦公室沒有購買速溶咖啡。所以那個辦公室的一些人聚在一起決定建立“咖啡角”。")]),a("p",null,"咖啡角的一名成員會購買一些速溶咖啡，而其他成員會付給他錢。有人喝咖啡比其他人多，所以增加了“半成員”的級別：半成員每週允許喝的咖啡限量，並可以支付其它成員支付的一半。")],-1)),a("p",null,[s[1]||(s[1]=n("管理這事非常操心。而我剛讀過《Unix 編程環境》這本書，想練習一下我的 ",-1)),i(e,{href:"https://en.wikipedia.org/wiki/AWK"},{default:p(()=>[...s[0]||(s[0]=[n("AWK",-1)])]),_:1}),s[2]||(s[2]=n(" 編程技能，所以我自告奮勇創建了一個系統。",-1))]),s[23]||(s[23]=r(`<p>第 1 步：我用一個數據庫來記錄成員及其應支付給咖啡角的欠款。我是以 AWK 便於處理的格式記錄的，其中字段用冒號分隔：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>member:john:1:22</span></span>
<span class="line"><span>member:jane:0.5:33</span></span>
<span class="line"><span>member:pratyush:0.5:17</span></span>
<span class="line"><span>member:jing:1:27</span></span></code></pre></div><p>上面的第一個字段標識了這是哪一種行（<code>member</code>）。第二個字段是成員的名字（即他們的電子郵件用户名，但沒有 @ ）。下一個字段是其成員級別（成員 = 1，或半會員 = 0.5）。最後一個字段是他們欠咖啡角的錢。正數表示他們欠咖啡角錢，負數表示咖啡角欠他們。</p><p>第 2 步：我記錄了咖啡角的收入和支出：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>payment:jane:33</span></span>
<span class="line"><span>payment:pratyush:17</span></span>
<span class="line"><span>bought:john:60</span></span>
<span class="line"><span>payback:john:50</span></span></code></pre></div><p>Jane 付款 $33，Pratyush 付款 $17，John 買了價值 $60 的咖啡，而咖啡角還款給 John $50。</p><p>第 3 步：我準備寫一些代碼，用來處理成員和付款，並生成記錄了新欠賬的更新的成員文件。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>#!/usr/bin/env --split-string=awk -F: -f</span></span></code></pre></div><p>釋伴行（<code>＃!</code>）需要做一些調整，我使用 <code>env</code> 命令來允許從釋伴行傳遞多個參數：具體來説，AWK 的 <code>-F</code> 命令列參數會告訴它字段分隔符是什麼。</p><p>AWK 程序就是一個規則序列（也可以包含函數定義，但是對於這個咖啡角應用來説不需要）</p><p>第一條規則讀取該成員文件。當我運行該命令時，我總是首先給它的是成員文件，然後是付款文件。它使用 AWK 關聯數組來在 <code>members</code> 數組中記錄成員級別，以及在 <code>debt</code> 數組中記錄當前欠賬。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$1 == &quot;member&quot; {</span></span>
<span class="line"><span>   members[$2]=$3</span></span>
<span class="line"><span>   debt[$2]=$4</span></span>
<span class="line"><span>   total_members += $3</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>第二條規則在記錄付款（<code>payment</code>）時減少欠賬。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$1 == &quot;payment&quot; {</span></span>
<span class="line"><span>   debt[$2] -= $3</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>還款（<code>payback</code>）則相反：它增加欠賬。這可以優雅地支持意外地給了某人太多錢的情況。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$1 == &quot;payback&quot; {</span></span>
<span class="line"><span>   debt[$2] += $3</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>最複雜的部分出現在有人購買（<code>bought</code>）速溶咖啡供咖啡角使用時。它被視為付款（<code>payment</code>），並且該人的債務減少了適當的金額。接下來，它計算每個會員的費用。它根據成員的級別對所有成員進行迭代並增加欠款</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$1 == &quot;bought&quot; {</span></span>
<span class="line"><span>   debt[$2] -= $3</span></span>
<span class="line"><span>   per_member = $3/total_members</span></span>
<span class="line"><span>   for (x in members) {</span></span>
<span class="line"><span>       debt[x] += per_member * members[x]</span></span>
<span class="line"><span>   }</span></span>
<span class="line"><span>}</span></span></code></pre></div><p><code>END</code> 模式很特殊：當 AWK 沒有更多的數據要處理時，它會一次性執行。此時，它會使用更新的欠款數生成新的成員文件。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>END {</span></span>
<span class="line"><span>   for (x in members) {</span></span>
<span class="line"><span>       printf &quot;%s:%s:%s\\n&quot;, x, members[x], debt[x]</span></span>
<span class="line"><span>   }</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>再配合一個遍歷成員文件，並向人們發送提醒電子郵件以支付他們的會費（積極清賬）的腳本，這個系統管理咖啡角相當一段時間。</p><hr>`,22)),a("p",null,[s[4]||(s[4]=n("via: ",-1)),i(e,{href:"https://opensource.com/article/19/2/drinking-coffee-awk"},{default:p(()=>[...s[3]||(s[3]=[n("https://opensource.com/article/19/2/drinking-coffee-awk",-1)])]),_:1})]),a("p",null,[s[9]||(s[9]=n("作者：",-1)),i(e,{href:"https://opensource.com/users/moshez"},{default:p(()=>[...s[5]||(s[5]=[n("Moshe Zadka",-1)])]),_:1}),s[10]||(s[10]=n(" 選題：",-1)),i(e,{href:"https://github.com/lujun9972"},{default:p(()=>[...s[6]||(s[6]=[n("lujun9972",-1)])]),_:1}),s[11]||(s[11]=n(" 譯者：",-1)),i(e,{href:"https://github.com/wxy"},{default:p(()=>[...s[7]||(s[7]=[n("wxy",-1)])]),_:1}),s[12]||(s[12]=n(" 校對：",-1)),i(e,{href:"https://github.com/wxy"},{default:p(()=>[...s[8]||(s[8]=[n("wxy",-1)])]),_:1})]),a("p",null,[s[15]||(s[15]=n("本文由 ",-1)),i(e,{href:"https://github.com/LCTT/TranslateProject"},{default:p(()=>[...s[13]||(s[13]=[n("LCTT",-1)])]),_:1}),s[16]||(s[16]=n(" 原創編譯，",-1)),i(e,{href:"https://linux.cn/"},{default:p(()=>[...s[14]||(s[14]=[n("Linux中國",-1)])]),_:1}),s[17]||(s[17]=n(" 榮譽推出",-1))])])}const C=t(g,[["render",u]]);export{x as __pageData,C as default};
